{"filename":"routes.py","content":"from flask import Blueprint, request, jsonify, current_app
from . import models

bp = Blueprint("api", __name__, url_prefix="/api")

def _note_to_dict(row):
    return {
        "id": row[0],
        "title": row[1],
        "content": row[2],
        "createdat": row[3],
    }

@bp.route("/notes", methods=["GET"])
def get_notes():
    db = models.get_db()
    cursor = db.execute("SELECT id, title, content, createdat FROM note")
    notes = [_note_to_dict(row) for row in cursor.fetchall()]
    return jsonify({"success": True, "data": notes}), 200

@bp.route("/notes", methods=["POST"])
def create_note():
    data = request.get_json() or {}
    title = data.get("title", "").strip()
    if not title:
        return jsonify({"success": False, "error": "Title must not be empty"}), 400
    content = data.get("content")
    createdat = data.get("createdat")
    db = models.get_db()
    cursor = db.execute(
        "INSERT INTO note (title, content, createdat) VALUES (?, ?, ?)",
        (title, content, createdat),
    )
    db.commit()
    new_id = cursor.lastrowid
    return jsonify({"success": True, "data": {"id": new_id}}), 201

@bp.route("/notes/<int:item_id>", methods=["GET"])
def get_note(item_id):
    db = models.get_db()
    cursor = db.execute(
        "SELECT id, title, content, createdat FROM note WHERE id = ?", (item_id,)
    )
    row = cursor.fetchone()
    if row is None:
        return jsonify({"success": False, "error": "Note not found"}), 404
    return jsonify({"success": True, "data": _note_to_dict(row)}), 200

@bp.route("/notes/<int:item_id>", methods=["PUT"])
def update_note(item_id):
    data = request.get_json() or {}
    title = data.get("title")
    if title is not None and not str(title).strip():
        return jsonify({"success": False, "error": "Title must not be empty"}), 400
    content = data.get("content")
    createdat = data.get("createdat")
    db = models.get_db()
    # Build dynamic SET clause based on provided fields
    fields = []
    values = []
    if title is not None:
        fields.append("title = ?")
        values.append(title)
    if content is not None:
        fields.append("content = ?")
        values.append(content)
    if createdat is not None:
        fields.append("createdat = ?")
        values.append(createdat)
    if not fields:
        return jsonify({"success": False, "error": "No fields to update"}), 400
    values.append(item_id)
    sql = f"UPDATE note SET {', '.join(fields)} WHERE id = ?"
    cursor = db.execute(sql, tuple(values))
    db.commit()
    if cursor.rowcount == 0:
        return jsonify({"success": False, "error": "Note not found"}), 404
    return jsonify({"success": True, "data": {"id": item_id}}), 200

@bp.route("/notes/<int:item_id>", methods=["DELETE"])
def delete_note(item_id):
    db = models.get_db()
    cursor = db.execute("DELETE FROM note WHERE id = ?", (item_id,))
    db.commit()
    if cursor.rowcount == 0:
        # Deletion failed because note did not exist
        return jsonify({"success": False, "error": "Note not found"}), 404
    return jsonify({"success": True, "data": {"id": item_id}}), 200"}
